quests[13501] = { id = 13501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13504] = { id = 13504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatterspear Laborers", description = "There are a large number of Shatterspear trolls picking through the ruins to the north and northeast. I suspect that they're looking for magical artifacts, but none of our scouts have reported the discovery of anything of significance turning up from their digs. They may well just be fueling their war.\n\nOne thing is fairly certain though: less laborers would slow down their offensive, so less laborers is what they're going to get. You in?", sourceObjective = "Kill 10 Shatterspear Laborers.", completion = "Good work. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13505] = { id = 13505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Highborne", description = "There are several ruins similar to these spread through Darkshore, many of them inhabited by the troubled spirits of the Highborne. Out of mild courtesy for their cursed souls, we haven't been overly proactive about stripping the ruins of artifacts, but those hesitancies vanish in light of this new troll threat.\n\nWhile you're aiding the Sentinels in their goals within the ruins, please collect any artifacts that you stumble upon and bring them back to me. I would like to preserve what little I can.", sourceObjective = "Retrieve 8 Highborne Relics.", progress = "Were you able to recover any artifacts?", completion = "Perfect! Thank you so much. I would hate to lose more records of our culture to war - far too much has been sacrificed already.", sourceObjectiveStatus = "unverified-source-field" }
quests[13506] = { id = 13506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reason to Worry", description = "These appear to be orders dispatched to the overseers at the ruins from a superior in the Shatterspear War Camp. Most of the document contains negligible strategic value, but a couple lines stick out to you.\n\n\"We captured another night elf spying on our operation. She has been taken back to the camp to be tortured for more information. Keep an eye out for additional spies - we cannot afford for our operation to be compromised.\"\n\nThe Lieutenant will surely want this information.", sourceObjective = "Bring the Shatterspear Orders to Lieutenant Morra Starbreeze at the Ruins of Mathystra.", progress = "Yes, {class}?", completion = "\"Another?\" They have more than one. I will not leave any of my people to be tortured, we must act quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13507] = { id = 13507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denying Manpower", description = "To the north, the Shatterspear have a war camp where they are constructing their catapults. The camp is guarded by some of their mystics, but I've started receiving reports that there are sightings of orcs and tauren there as well.\n\nI don't want to make any assumptions as to what that suggests, but I do want you to go in and kill them before they can make any further strikes on our Sentinels.", sourceObjective = "Kill 6 Horde Enforcers and 6 Shatterspear Mystics.", completion = "Excellent work. One more threat we can worry a bit less about. We'll continue the offensive while they are still off-guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[13508] = { id = 13508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Response", description = "I have a scout that we lost contact with a couple days ago. I assumed her dead, but it appears that she's been captured. The trolls indicate that they have at least two captives though... the only other person that comes to mind is Alanndarian Nightsong, a civilian that was in the area against my advisement early yesterday.\n\nThe Shatterspear have established a war camp to the north - it is almost certainly where any of their prisoners are being taken. Find them and free them if you're able.", sourceObjective = "Locate the night elf prisoners at the Shatterspear War Camp.", completion = "<Alanndarian looks very pale, though shallow breaths betray the life that remains in her.>\n\nYou're here...  to save me? A bit later... than I hoped.", sourceObjectiveStatus = "unverified-source-field" }
quests[13509] = { id = 13509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Supplies", description = "The trolls are building their forces and supplies at the war camp to the north. When they feel they are ready, they will almost certainly launch their attack on Lor'danel from that location. It shouldn't take us long to rout this rabble, but I'm not one for taking unnecessary risks.\n\nI want you to fight your way into the war camp and set fire to any stockpiles of supplies that you see. The setback should buy us quite a bit of time before they can muster a counterattack.", sourceObjective = "Destroy 12 Shatterspear Armaments.", completion = "Excellent work. That should slow them down a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13510] = { id = 13510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timely Arrival", description = "It's good to see you. I wasn't looking forward to enduring what Alanndarian did, so the rescue is somewhat welcome.\n\nI saw the troll leader before I was captured, and thought I had the perfect opportunity to kill him, but he's protected by some sort of magic shield. Morra needs to know before she mounts her assault, but first, we need to get out of here.\n\nHelp me to the dock - I'll make my way to Lor'danel via water, and you can go back to Morra with the intel.", sourceObjective = "Escort Sentinel Aynasha to safety.", completion = "Some sort of shield you say? We might have a way around that. Balthule had an idea for breaking whatever protective enchantments their shaman had, so it might work on this too. Thank you for saving Aynasha and bringing me this information - it may well make the difference in our battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[13511] = { id = 13511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Bitter Wish", description = "Morra sent you? I should have listened to her - it's just hard to take trolls seriously I guess.\n\n<Alanndarian lets out a weak chuckle.>\n\nIt's way too late for that anyway. We're mortal now... this is the fate we have to face, one way or another. I've had time to accept that.\n\nI have one request though... kill the torturer that did this to me. They call him Rit'ko... you can find him just ahead with the other prisoner.\n\n<Alanndarian offers a small smile, then winces and slumps back over in pain.>", sourceObjective = "Kill Rit'ko, the Shatterspear Torturer.", completion = "Alanndarian is dead then. That saddens me greatly, but it is not entirely unexpected. I expect no mercy from these savages, and will show them none.", sourceObjectiveStatus = "unverified-source-field" }
quests[13512] = { id = 13512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Strikes", description = "Striking at the head of the beast doesn't work if there's another head to replace it. Before we can kill their leader, we need to kill the subleaders that may try to step up. Right now, they are not as well defended, and you should be able to best them without much support.\n\nTake this dryad spear and hunt them down. The poison on its tip should slow their incantations. My scouts reported one inside the water chamber in the ruins to the east and the other past the remains of the tower to the southwest.", sourceObjective = "Kill Sheya Stormweaver and Lorenth Thundercall.", completion = "You've shown a great deal of talent for one so young. Good work. It seems the final battle is before us.", sourceObjectiveStatus = "unverified-source-field" }
quests[13513] = { id = 13513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Brink", description = "I've already been working on something for breaking down their protective wards. With a focus based in their power and a bit of druidic magic, we should be able to breach their shields.\n\nFind their shaman to the east and southeast and recover several of their amulets. I will prepare them and imbue an arrow that you can deliver to Sandrya Moonfall for the attack.", sourceObjective = "Retrieve 6 Shatterspear Amulets.", progress = "Did you recover the amulets?", completion = "These will do perfectly. I will prepare them for Sandrya - you are sure to be dispatched to meet with her shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13514] = { id = 13514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancients' Ire", description = "Come to join the offensive? If you're looking for Sandrya Moonfall, she's leading the attack on the Shatterspear leader at the cave in the back of the vale, you can meet her there.\n\nWhile you're here though, we could certainly use your help with routing the rest of their tribe. Go ahead and take the company of one of the Vengeful Protectors there and see to it that every last building is destroyed and every last troll killed. We can't have them coming back for revenge when we're less prepared, can we?", sourceObjective = "Utilize a Vengeful Protector to kill 30 Shatterspear trolls and destroy 6 Shatterspear Structures.", progress = "I have no yearning for war, but I've had sufficient reason to worry that we'd get rusty after so much time away from the front lines. It's good to see that the Sentinels and the ancients are every bit as dangerous as I remember them.", completion = "You performed excellently up there! We are fortunate to have you with us.\n\nI haven't yet received word regarding their leader. If you haven't spoken with Sandrya at the cave in the back of the vale, be sure to do so before you depart.", sourceObjectiveStatus = "unverified-source-field" }
quests[13515] = { id = 13515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Threat", description = "Their leader and his guard are before us. My Sentinels are ready to take care of his guard, we only awaited this arrow to seal their leader's fate.\n\nLet me know when you are prepared to attack. As soon as my Sentinels engage, I will shatter the leader's shield, and we will assault him together. Strike swiftly and we can rout this threat to our lands here and now.\n\nWe await only you - speak to me when ready.", sourceObjective = "Speak to Sandrya Moonfall to start the attack, and aid her in killing Jor'kil the Soulripper", progress = "As it should be.", completion = "We owe a great debt to you for all that you've done to see this battle through.\n\nNot often can we claim victories so decisively, but it seems there's far more to this plot than just the Shatterspear. If you haven't already checked his body for information, make sure to do so before you leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[13518] = { id = 13518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Wave of Survivors", description = "It's too late for Laird, he didn't make it in time.\n\nThe last wave of night elves from Auberdine attempted to escape a couple of hours ago. They stayed in their old home, clinging to the hope that it could be salvaged, but it seems they were finally forced out. I fear many of them won't make it, like Laird did not.\n\nQuickly, go down the coast to the west and find any survivors that you can. We're sending Sentinels and Hippogryphs down, but every moment counts - we need to know which ones might make it.", sourceObjective = "Locate any refugees from Auberdine that are still alive.", progress = "Their pride kept them in Auberdine for this long, but none deserve such a cruel fate.", completion = "Thank you, {class}. Some of them surely would not have made it without you.\n\nWe'll be taking the wounded to the main building once we have them all safely back in town. Perhaps you can meet us there later?", sourceObjectiveStatus = "unverified-source-field" }
quests[13519] = { id = 13519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight's Hammer", description = "A group of Twilight's Hammer cultists has set up camp southwest of here.  They're preparing an army of water elementals to use against Lor'danel.\n\nTheir leader, High Cultist Azerynn, has pacts with the dark Old Gods that grant his sect power over the elements.  Go and deal with them before it's too late, {name}.\n\nThe cataclysm has left the elemental spirits in disarray... it's only a matter of time until they have enough elementals to overcome our defenses.", sourceObjective = "Slay High Cultist Azerynn and 10 Twilight Fanatics in the Twilight Encampment.", completion = "You've done well, {name}.  The Twilight's Hammer is a dangerous cult.  It would be foolish to underestimate the danger they represent.", sourceObjectiveStatus = "unverified-source-field" }
quests[13520] = { id = 13520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of the Seas", description = "It is good to see you. You were key in ensuring that our loved ones made it home, and I hold some hope that you may yet help us further.\n\nLike Laird, their wounds will be grave - every one of them battered by the coast and assaulted by the elementals. I am doing what I can, but it seems that those elementals hosted a toxin that is weakening their ability to heal. I believe I can concoct a salve, but I will need secretion from the muscles of the clams that inhabit this coast. Can you help me?", sourceObjective = "Collect 16 Encrusted Clam Muscles.", progress = "Did you bring muscles from the clams? I worry that our time grows very short.", completion = "This will do perfectly. Thank you so much!\n\nI suspect they will want to thank you personally should they recover, so perhaps you can stop by later on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13521] = { id = 13521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 413", description = "Greetings!\n\nI'm helping Tharnariun here try to unravel what's been corrupting the wildlife in the area. I've set up some machines in the field that can analyze animal parts and possible corruption agents. If you can get me some good samples, we can get to the bottom of this affliction quickly.\n\nThe first machine is Buzzbox 413. I set it up on the beach just east of town. I'll need you to gather some flesh from the nearby corrupted tide crawlers and bring it to the machine so that I can analyze it.", sourceObjective = "Gather 4 Corrupted Tide Crawler Flesh samples and bring them to Buzzbox 413 for analysis.", progress = "<Buzzbox 413 hums at you expectantly.>", completion = "<The machine crackles loudly, and then Wizbang's static-ridden voice becomes audible.>\n\nLovely! I hope you didn't kill too many of them. We're not trying to wipe out the population, we just need to get to the source of this corruption quickly! I'm proceeding with the analysis now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13522] = { id = 13522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from the Water", description = "Some of the survivors of this last Auberdine attack are still trying to make it up the coast to safety. We only caught word that they were coming within the last hour. I wish that we had more warning...\n\nThe coastline west of us is swarming with vile spray, vicious little water elementals. We need to clear them out if any of the survivors are to have a chance of making it to Lor'danel. Depart immediately and kill every elemental you see.", sourceObjective = "Kill 8 Vile Spray.", completion = "Your efforts are very much appreciated. Since the Cataclysm, the elementals have been out of control. We have little hope of taking back Auberdine without extinguishing their presence first.", sourceObjectiveStatus = "unverified-source-field" }
quests[13523] = { id = 13523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Over the Tides", description = "Do not worry about me.  My wounds are deep and death will soon come to me.\n\nIt is all up to you now... you must stop the Twilight's Hammer.\n\nThe Old Gods they worship have granted them power over the restless water spirits... but that power is tenuous.  Channel Elune's presence through this orb once the elementals have been defeated.\n\nUse the power of Elune to banish the spirits permanently.", sourceObjective = "Use the Orb of Elune on the remains of 6 Enraged Tidal Spirits.", progress = "My lifeforce abandons me... even now...", completion = "You've succeeded... it hasn't all been in vain...\n\nMy time approaches.  Go now, {name}, and may Elune protect you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!You will be able to choose one of these rewards:", sourceObjective = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13525] = { id = 13525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Happening to the Blackwood Furbolg?", description = "Our ancestors lived alongside the Blackwood furbolgs for generations. But recently, we have lost contact with their settlements deeper in the forest. One of their larger villages, Blackwood Hold, can be found to the south.\n\nTravel there and find Elder Brolg. Ask him why his people have withdrawn from us and offer your help, if necessary.", sourceObjective = "Speak with Elder Brolg at Blackwood Hold.", completion = "Why have you come here, outsider?\n\n<You tell the elder that you were sent by Foriel Broadleaf at the Grove of the Ancients. He seems to relax slightly.>\n\nThe elf is right. The forces of Felwood have seeped into Darkshore and sickened my people.", sourceObjectiveStatus = "unverified-source-field" }
quests[13526] = { id = 13526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear's Paw", description = "The foul satyr of Felwood have started to introduce their poison into Darkshore, into our lands. Their corruption kills the land and twists the creatures who live in it. My people are no exception.\n\nOur magic alone is not enough to bring them back to their senses. There is an herb, called bear's paw, that we use to break fevers and fortify the weak. With its help, we may be able to break the influence of the satyr. The herb grows in the wilds around the village.", sourceObjective = "Bring 8 stalks of Bear's Paw to Elder Brolg at Blackwood Hold.", progress = "Have you gathered the bear's paw?", completion = "These are poor, weak stalks, but they are all we have. The corruption spreads quickly, even among the plants of the forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13527] = { id = 13527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Accounting for Taste", description = "<The machine buzzes for a few moments  before Wizbang's voice breaks through.>\n\nInteresting! The source of this corruption definitely came from something external--no surprises there--but it appears that in this case they've been eating something foul. A large mammal probably. Most likely a bear.\n\nSearch the beach for a bear carcass for me. Slightly east of there would make the most sense, on the inland side of the beach. Bring me the sample back at town.", sourceObjective = "Retrieve a sample from a decomposing bear carcass east of Buzzbox 413.", progress = "Welcome back! Did you find that bear sample that I was looking for?", completion = "This definitely looks like the stuff they were eating. Let me take a closer peek...", sourceObjectiveStatus = "unverified-source-field" }
quests[13528] = { id = 13528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 723", description = "There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now.\n\nBuzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.", sourceObjective = "Gather 6 samples of Corrupted Thistle Bear Guts and bring them to Buzzbox 723 for analysis.", progress = "<Buzzbox 723 hums at you expectantly.>", completion = "<Static precedes Wizbang's distorted voice.>\n\nThe results are coming in now. We should have some information on how the bears contracted this in just a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[13529] = { id = 13529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption's Source", description = "I rushed here as soon as I heard the news from Wizbang. I know who's behind this mess now. Zenn Foulhoof.\n\nHe came over from Teldrassil after he was chased out for performing perverse magics. The kinds of corruption he employs are not welcome among my people, and it seems he's taken it a step further this time, perhaps as some form of revenge.\n\nZenn's been given too many chances, it's time we remove this threat to all that is natural. Kill Zenn and his minions, and then find me back in Lor'danel.", sourceObjective = "Kill Zenn Foulhoof and 8 Vile Grell in Cliffspring Hollow.", progress = "This is never desirable work. Zenn was not always the corrupt being that you now see. Sadly, he is behind reproach at this point. Much of the damage that he has done to nature is irreversible.", completion = "It is done then. Thank you. I only hope that the wildlife here will see more peace with his passing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13537] = { id = 13537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste for Grouper", description = "Between boat rides and building, I'm exhausted... and hungry. You know what sounds tasty? Fish. Fish sound delicious.\n\nDarkshore is known for its grouper. If you fish me up some, I'll make it worth your time.", sourceObjective = "Use your fishing skill to obtain 4 Darkshore Grouper.", progress = "<Johnathan's belly grumbles as you approach.>\n\nCouldn't have said it better with words.", completion = "It looks like fishing's your thing. My belly appreciates the gift.\n\nI'm thinking you would get more use out of this pole than I would. Have at it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southern Sabotage", description = "The three towers south of the Wintergrasp river are draining power from the Fortress! \n\nDestroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.", completion = "I heard the explosion from here! Excellent job - we've already begun rerouting the power into the Titan relic to super-charge our own forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toppling the Towers", description = "While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.\n\n\"Attack him where he is unprepared, appear where you are not expected.\"\n\n{name}, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.\n\nReturn to me once you've destroyed a tower.", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.", progress = "My disgust for Warlocks is only exceeded by my hate for the undead. However, they can both prove useful at times.", completion = "Now in order to kill the enemy, our men must be roused to anger; that there may be advantage from defeating the enemy, they must have their rewards. I hope that these are sufficient for your service to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13542] = { id = 13542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Wind", description = "If we're going to take the Ruins of Auberdine back from the Twilight's Hammer, the elementals that they've summoned must be dealt with on a permanent basis.\n\nThat's where you come in.\n\nLook, I don't expect you to retake the town, but while we're healing up here, you can soften them up for us.\n\nTo permanently deal with the frenzied cyclones, head west, kill them, take their bracers, and put them in the moonwell. That will destroy the bracers and keep those elementals from being resummoned.", sourceObjective = "Use the moonwell in the Ruins of Auberdine to destroy 8 sets of Frenzied Cyclone Bracers.", completion = "I cannot thank you enough, {name}. Now we'll have a fighting chance to retake the ruins as soon as we are in better health.", sourceObjectiveStatus = "unverified-source-field" }
quests[13543] = { id = 13543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Hammers to Break", description = "I've flown through the ruins of Auberdine on a scouting mission. There are three Twilight's Hammer cultists that are responsible for the elementals that have overrun the destroyed town.\n\nHead west into the ruins. Seek out and slay Cloudtamer Wildmane, Windmaster Tzu-Tzu, and Skylord Braax.\n\nOnly then will Sentinel Selarin and her forces stand a chance of taking back their home.", sourceObjective = "Slay Cloudtamer Wildmane, Windmaster Tzu-Tzu, and Skylord Braax.", completion = "Without those three coaxing them, perhaps the flow of elementals into the Ruins of Auberdine will be stemmed.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13544] = { id = 13544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear's Blessing", description = "Before the bear's paw can be used to cleanse the afflicted, it must be completed and blessed. To the north of the village roams a tallstrider named Fleetfoot. You'll need its tailfeathers to complete the herb bundle.\n\nBring the tailfeathers and the bear's paw bundle to the ancient bear statue in the ruins around the Grove of the Ancient, further north of where you'll find Fleetfoot.\n\nWhile at the shrine, combine the tailfeathers with the bear's paw and receive the bear spirit's blessing.", sourceObjective = "Elder Brolg at Blackwood Hold wants you to bring him the Blessed Herb Bundle.", progress = "Have you visited the old bear statue?", completion = "<Elder Brolg accepts the blessed bundle from you and looks over it.>\n\nThis is exactly what we needed. The bear's spirit favors us and there may be hope for my brothers after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[13545] = { id = 13545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Afflicted", description = "With the sacred herbs and the bear's blessing, you must use this herb bundle to cleanse my brothers. The corruption spilling over from Felwood has driven them mad and they will attack any who come near. Expect the afflicted Blackwood to be angry with you until you have slain the spirits of corruption that haunt them.\n\nWhen you have freed my brothers from their madness, return to me.", sourceObjective = "Elder Brolg wants you to use the Blessed Herb Bundle to cleanse 7 furbolg of Blackwood Hold and kill the Spirits of Corruption driving them mad.", progress = "Have your efforts and the bear's blessing cleansed my brothers?", completion = "You have done well. My people have begun to emerge from their madness, but they will fall back into it if we do not deal with the source of the corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[13546] = { id = 13546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defiler", description = "The Jadefire satyrs of Felwood have found their way into Darkshore, tainting the land, water, and creatures they encounter. You've seen what their corruption has done to my people and their homes. If we do not turn back the satyrs, all of us will share that fate.\n\nWithin the cave to the east is Sharax the Defiler, the satyr responsible for the ills of the Blackwood. Slay him, {name}, and free us from his influence. Show the satyr that the Blackwood will not lay down and die so easily.", sourceObjective = "Elder Brolg at Blackwood Hold wants you to kill Sharax the Defiler.", progress = "Have you defeated the satyr who poisons our lands?", completion = "Thank you, {name}. You are a hero to my people. Without you, we would be doomed to madness and death. May the bear spirit always watch over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13547] = { id = 13547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coaxing the Spirits", description = "Your friends back at the refugee camp are unaware of the true and imminent danger that the Twilight's Hammer cultists have already brought into the world.\n\nFor you to deal with that, we'll first need to get some help from the dead of Auberdine.\n\nSearch through the ruins of the town and find the corpses of Thundris Windweaver, Elissa Starbreeze, Taldan, and Caylais Moonfeather. Coax the spirits from their bodies and then return with them to me here.", sourceObjective = "Coax the spirits from Thundris Windweaver, Elissa Starbreeze, Taldan, and Caylais Moonfeather.", completion = "So much death and pain. Can there be any doubt that there is more yet to come?\n\nAll I wish to do is move onward into the Goddess's embrace as do these others.\n\nBut first, let us see if we can keep even more misery and destruction from being spread.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tails Up", description = "Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females!\n\nToo bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him?\n\nPut the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each.", progress = "No, that just won't do. Please return when you have the female leopards and bears that I'll need for the arduous journey back home.", completion = "Very fine specimens indeed, {name}! These are sure to provide many hours of curious speculation amongst my colleagues back home.", sourceObjectiveStatus = "unverified-source-field" }
quests[13554] = { id = 13554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cure In The Dark", description = "<Some unintelligible speech spews forth from the machine before you make out Wizbang's voice again.>\n\nDuskrats! They've been eating the duskrats! Those little buggers only come from one place, a cave against the cliff-face to the east. Find a path up to the northeast and look for an opening under the waterfall.\n\nThe duskrats there are either getting into something nasty or someone's intentionally spreading some agent through them - in either case, just bring me back several samples of the stuff!", sourceObjective = "Retrieve 6 Samples of Foul Ichor from the creatures inside Cliffspring Hollow.", progress = "Did you get to the stuff? The sooner I can start working on a cure, the more animals we can save!", completion = "This should be plenty! Thanks so much! I'll get working on a cure for this nastiness immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggs for Dubra'Jin", description = "How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin.\n\nHow ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid!\n\nWe need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.", sourceObjective = "Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs.", progress = "Who woulda thought the great Dubra'Jin be wantin' so many eggs? What he gonna do with them anyway?", completion = "One, two, three,... hehe, that be a good number o' them, mon! Now we be safe for quite some time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13557] = { id = 13557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearer of Good Fortune", description = "This key appears to be for the animal cages spread throughout Cliffspring Hollow. Tharnariun would surely appreciate if you took advantage of the situation to free some of the uncorrupted duskrats and thistle bears that are still being held captive.", sourceObjective = "Free 8 Uncorrupted Thistle Bears or Uncorrupted Duskrats from the cages in Cliffspring Hollow.", progress = "Yes, {race}?", completion = "I am pleased to hear that you were able to free some of the remaining wildlife. With a bit of good fortune, we will find the cure for the corruption that the others have faced before any more of them die.", sourceObjectiveStatus = "unverified-source-field" }
quests[13558] = { id = 13558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Down the Thunder", description = "Aetherion is almost in our world, but he can still be dealt with!\n\nAt the end of the dock floats a ritual orb. I want you to use it to complete the ritual, beckoning the elemental lord down from his vortex.\n\nTrust me, {name}, I and the other spirits that you have freed will greatly weaken Aetherion. However, it will be up to you to finish him off for good and save the Kaldorei people of Darkshore from utter destruction.\n\nDeliver his essence to Corvine Moonrise at the refugee camp so he will know.", sourceObjective = "Use Aetherion's Ritual Orb and obtain Aetherion's Essence.", progress = "You have returned. What news do you bring?", completion = "Yalda? The spirits of others from the Ruins of Auberdine?\n\n<The druid ponders what you've conveyed about your adventure in the ruins.>\n\nI remember them all. They will be dearly missed, but they have moved on into the Goddess's embrace and that is for the best.\n\nAnde'thoras-ethil, may your troubles be diminished, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Tribute", progress = "No ordinary tributes were good enough for the great Hodir when he walked among the frost giants.\n\nHe might not be with us anymore, but we've kept the tradition of offering tribute to his strength and wisdom.  It would do much for your renown to partake in this tradition, small {class}.", completion = "The Sons of Hodir accept your tribute, small one.  You continue to prove your worth as an ally in more ways than one." }
quests[13560] = { id = 13560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ocean Not So Deep", description = "You look like an able sort!\n\nThere are a great number of wrecks off of the coast here... most old, some new. For quite some time, I've been trying to get at their holds and put their valuables to more use, but there's a nasty infestation of murlocs that seem to have other ideas. I've sent scores of adventurers and none have returned.\n\nWorry not, I've learned my lesson, and that is not your fate. Swim to the due north and look for Gary. He'll explain the new plan. It's pretty simple really.", sourceObjective = "Gorbold Steelhand at Lor'danel wants you to speak to Gary for further instructions.", completion = "The decoys worked then? Great to hear it! Don't you worry yourself one bit about the treasures. Me and Gary will take care of the rest this time around.\n\nTruth be told, if something went wrong again and I lost any more of you adventurer types, I'm pretty sure they'd kick me out of town.", sourceObjectiveStatus = "unverified-source-field" }
quests[13561] = { id = 13561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solace for the Highborne", description = "I have come to Bashal'Aran to grant peace to the troubled spirits of the Highborne, but I find my hand hesitates with each blow. If you would like to aid me, you would have my gratitude.", sourceObjective = "Kill 6 Cursed Highborne and 6 Writhing Highborne.", progress = "Is it done?", completion = "You have my thanks. Though they may not be able to show it, you have the thanks of the Highborne spirits as well.\n\nFare safely, traveler.", sourceObjectiveStatus = "unverified-source-field" }
quests[13562] = { id = 13562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Flame of Bashal'Aran", description = "It is in times like these that we are forced to stop and examine our way of life. We are mortal now, and no matter how much we desire otherwise, we are deserving of our new place in this world.\n\nBashal'Aran, down the road to the south, once a city of our ancestors, it now is home to their cursed ghosts. We held hope of salvation for them as with ourselves, but we have left them in torment for too long. It is time to extinguish the Final Flame of Bashal'Aran.", sourceObjective = "Extinguish the Final Flame of Bashal'Aran.", completion = "You have our thanks. It is time that we leave the past behind us, and start looking to our future.", sourceObjectiveStatus = "unverified-source-field" }
quests[13563] = { id = 13563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Love Eternal", description = "I would like to extend my gratitude for saving us. I would call myself fortunate, but my beloved, Anaya, lays long dead. I am alone and deeply troubled, and sadly, I require your aid yet again.\n\nWandering the woods of Darkshore after my rescue, I found myself in the ruins of Bashal'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.", sourceObjective = "Free the spirit of Anaya Dawnrunner and retrieve her pendant.", progress = "I somehow avoided being inflicted with the same toxin that the other survivors now endure. I cannot help but be envious of them to a degree though... living an eternity alone seems not worth living at all.\n\nI miss you so much, Anaya.", completion = "Thank you, {name}. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief...", sourceObjectiveStatus = "unverified-source-field" }
quests[13564] = { id = 13564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Companion", description = "Please help... I can barely sit up.\n\nMy friend, a bear named Grimclaw, he's not here. I sent him ahead to let the Sentinels know we were coming before we left Auberdine, but he never arrived. I sensed something might be amiss as we were leaving, but with the evacuation, I never had a chance to act on it.\n\nIf he's injured, there's only one place that he would go - the Withering Thicket, north of Auberdine, down the road to the south from here. Bring him back to me safely... he's my only family.", sourceObjective = "Locate Grimclaw.", completion = "Greetings, traveler. You seem to have an interest in my friend here. You're here on behalf of his friend Volcor then I imagine? If Volcor didn't come himself, he must be injured as well. I hope he recovers quickly.\n\nGrimclaw is too injured to be moved far and he's going to need some immediate treatment. I'm afraid I can't let you take him back just yet, but perhaps you can help me while I tend to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13565] = { id = 13565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twice Removed", description = "We cannot condone reckless violence - it is not our nature. However, there are times when the consequences of avoiding battle are too tangible to ignore, as is the case with these naga.\n\nWhen the earth in the area shattered, a small section of ruins rose to our east. These ruins once housed those loyal to Queen Azshara, and it seems her kind have returned in search of something.\n\nTake this petrified root. You can use it on their fallen to raise ents to aid you. Deal with them and their leader swiftly.", sourceObjective = "Use the Petrified Root to raise 6 Withered Ents and dispatch the naga leader, Lady Janira.", completion = "Thank you, ally. We shall keep a more vigilant eye should they return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13566] = { id = 13566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Materials", description = "While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife.\n\nI need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly.\n\nI need hair from the doe to the east, just avoid the stags.\n\nFinally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating.\n\nPlease do not harm any of them.", sourceObjective = "Retrieve 3 Moonstalker Whiskers, 3 Tufts of Mottled Doe Hair, and 3 Thistle Bear Fur.", progress = "Have you retrieved the materials that I asked for? And please tell me that you did not harm any of the animals in the process...", completion = "These will do perfectly. These are the final ingredients for an incense I've been working on. I will explain in just a moment, let me mix these in first.", sourceObjectiveStatus = "unverified-source-field" }
quests[13567] = { id = 13567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Stag", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Stag Spirit, take this incense to the woods just north of Bashal'Aran. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Stag Spirit.", completion = "I am the caretaker for my kind, leading not through force, but through wisdom and swift action. Wisdom is what carries us into the deeper forest when danger beckons and swiftness is what leaves our enemies basking in our absence.\n\nIn this wisdom, I see through to your true intentions, and I know that you are deserving of my blessing, the blessing of my swiftness. It can be yours, but know that the other spirits will not welcome you once you proceed - consider this carefully before accepting my boon.", sourceObjectiveStatus = "unverified-source-field" }
quests[13568] = { id = 13568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Moonstalker", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Moonstalker Spirit, take this incense to the land just south of the Ruins of Lornesta. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Moonstalker Spirit.", completion = "I share these forests willingly, accepting night elf kind into my home, and on occasion calling them friend. Though they have been tainted greatly in recent memory, I can see in you the same strength, honor, and spirit that first endeared them to me.\n\nIf you place value in the ferocity necessary to overcome all odds, then I am willing to call you my champion. Know now that if you side with my kind, the other spirits will not accept you, so consider your choice carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[13569] = { id = 13569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual Bond", description = "I will tend to Grimclaw until his rest is done - he will be ready to return very soon. I have one more task for you while we wait... a favor to grant you, really, should you recognize it.\n\nThe great wildlife spirits roam around us waiting and hoping for someone that will aid in stopping the destruction. They are with us as we speak even now, and with the materials  you brought me, I can grant you sight. Speak to these spirits, choose one, and return to me with their blessing.", sourceObjective = "Breathe in the incense in front of Keeper Karithus, and then choose the blessing of the Great Stag Spirit, the Great Thistle Bear Spirit, or the Great Moonstalker Spirit.\n\nKeep in mind that you can only receive the blessing of one spirit, so choose wisely.", completion = "So it is done. You have received the blessing of a great animal spirit, and I shall now complete the ritual for you. Please stand still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13570] = { id = 13570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembrance of Auberdine", sourceObjective = "I just want to offer my sincerest thanks for all that you've done for us. In my grief, I'm afraid that I didn't extend the gratitude that you truly deserve. We may not have made it here without you.\n\nKnow that you will always have friends here.\n\nAnd you needn't worry about my loneliness. Grimclaw has taken to keeping me company, and I have to say he's a more comforting companion than I would have expected.\n\nTake this, and go with all our blessings. Until we meet again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletcher's Lost and Found", sourceObjective = "Above the stale, unwashed stench, you catch a whiff of a familiar smell!  It appears as if this once-mighty adventurer has a real love for kungaloosh.\n\nPeeking through the bars, you can barely make out the recipe written on his arm....", sourceObjectiveStatus = "unverified-source-field" }
quests[13572] = { id = 13572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefire Braziers", description = "The satyrs of Felwood have started pouring their hate and corruption into our lands. They have sent Sharax the Defiler to subdue parts of the forest that we Blackwood call home.\n\nIn addition to poisoning the land, animals, and plants, he has set up Jadefire braziers throughout the village to help extend his control over our people. Destroying the braziers alone won't be enough to stop him, but it will help lessen his influence while you work with Elder Brolg to free our brothers.", sourceObjective = "Gren Tornfur at Blackwood Hold wants you to destroy 8 Jadefire Braziers.", completion = "Thank you, {name}. With your efforts, we might be able to save the Blackwood who remain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13573] = { id = 13573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion's Return", description = "It was only recently that we heard the news of Malfurion's awakening, mere moments before the Cataclysm occurred.\n\nAs soon as he regained consciousness, he gave a cryptic warning about the land splitting in two if something wasn't done and how all the shockwaves were converging here on Darkshore.\n\nHe then reportedly set off for somewhere in this vicinity.  I was sent here to find him, but I've found my hands full helping the refugees.\n\nPerhaps you could look for him to the southeast for us.", sourceObjective = "Look for Malfurion Stormrage at the Eye of the Vortex southeast of the Refugee Camp in Darkshore.", completion = "There is no time to waste, {class}.  It is taking every ounce of my power to keep Darkshore's entire landmass from being shattered and swept into the ocean... you must listen to me very carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[13575] = { id = 13575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land Is in Their Blood", description = "If we're to stabilize the forces of nature, we'll need every little bit of help we can get.  The furbolg of the Blackwood tribe have long inhabited the area and have strong ties to the land.\n\nTheir elder Shaman, Elder Brownpaw, wields great power over the elements -- his assistance would be invaluable.  See if you can obtain their aid.", sourceObjective = "Speak to Elder Brownpaw at the Blackwood Camp southwest of the Eye of the Vortex.", completion = "I have much respect for the great Malfurion Stormrage.  I cannot, however, leave my people in their time of need.  Maybe there is a way we can both help each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[13576] = { id = 13576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutual Aid", description = "With most of our brethren losing their way to madness or corruption, it would seem that we have little choice but to ally with you, {race}.  You can count on our aid... once you've proven we can count on yours.\n\nAs you can see, my people are having a bit of a problem with the fire elementals.  Help fight them and use this totem on their fiery remains.\n\nWe will return them to where they belong... whether they like it or not.", sourceObjective = "Use the Soothing Totem to absorb the remains of 8 Unbound Fire Elementals.", completion = "The element of fire is unique in that attacking it indiscriminately can often lead it to spreading further... succeeding only in agitating its flames.\n\nWe are wiser than that, {name}.  We are going to dispose of it properly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13577] = { id = 13577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Wildkin", description = "The wildkin were once numerous in Darkshore.  Such are their ties to the land that the Cataclysm that shattered Darkshore also decimated their numbers.\n\nThe wildkin Aroom is the last of his tribe and is a powerful elder with a strong connection to Elune.  His help will be most necessary in healing the land -- you will find him north of here at the Moontouched Den.", sourceObjective = "Speak to Aroom at the Moontouched Den north of the Eye of the Vortex.", completion = "A terrible sadness surrounds the creature.  Its eyes stare beyond you as you approach it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13578] = { id = 13578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aroom's Farewell", description = "<The creature hoots sadly as it addresses you.>\n\nAroom is last of tribe...\n\nOthers won't rest... need funeral pyre.  Bring Aroom the feathers of others.... let them rest.\n\nThen Aroom help you.", sourceObjective = "Obtain 8 Slain Wildkin's Feathers.", progress = "You bring others' feathers?", completion = "I thank you, {race}.  Soon my kin will rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13579] = { id = 13579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protector of Ameth'Aran", description = "Nothing will repair the land quicker than the strength of those who inhabit it.  We night elves are fortunate that some of our best allies just happen to be both the land and its inhabitants at once.\n\nThe Ancient of War known as Selenn was charged with guarding the ruins of Ameth'Aran, to the south.  Go there and seek his help.", sourceObjective = "Speak to Selenn at the Ruins of Ameth'Aran.", completion = "If the great Malfurion requires my presence, it is my duty to heed his call.  It is also my duty to protect these ruins, however.\n\nPerhaps you'll help me fulfill both my obligations, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13580] = { id = 13580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing the Elements", description = "Their fiery spirits are contained in the totem now.  Take it to the top of the Jagged Reef near the Blazing Strand and set it on the ground.\n\nThe totem's soothing energies will slowly wash over the elementals until their fury simmers down to calm.\n\nYou must protect the totem, for fire does not react favorably to the ritual of soothing.", sourceObjective = "Place the Charged Soothing Totem at the top of the reef near the Blazing Strand and protect it until the ritual is complete.", progress = "Is it done, {name}?", completion = "We are in your debt, {name}.  Perhaps now, with Malfurion's help, we can save the rest of Darkshore.", sourceObjectiveStatus = "unverified-source-field" }
quests[13581] = { id = 13581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwood Pledge", description = "It won't be immediate, but the elementals' anger will soon die down and my people will live to fight another day.\n\nI will go help you and Malfurion in any way that I can.", sourceObjective = "Return to Malfurion Stormrage at the Eye of the Vortex.", completion = "This is fortunate news, {name}.  The furbolg may seem little more than a savage race, but their ties to the land are ancient and their shamans are second to none.", sourceObjectiveStatus = "unverified-source-field" }
quests[13582] = { id = 13582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Fire", description = "We need special flame for ritual.  We need Elune's fire.\n\nHoroo's spirit wanders east of here.  Horoo carries torch of Elune.  Bring here so spirits rest.\n\nAroom thanks you.", sourceObjective = "Obtain Elune's Torch from Horoo the Flamekeeper.", progress = "You have torch?", completion = "<Aroom lets out a long low-pitched hoot.>\n\nFinally kin may rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13583] = { id = 13583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wildkin's Oath", description = "Wildkin with Elune.  Aroom in your debt now.\n\nAroom help you now.  Return to Malfurion, I join you soon.", sourceObjective = "Return to Malfurion Stormrage at the Eye of the Vortex.", completion = "The wildkin were once the guardians of the land.  It is good to hear they haven't all forgotten their old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[13584] = { id = 13584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Earth", description = "I would be neglecting my responsibility if I abandoned my post just now, with so many elementals out of control in the ruins.\n\nLet us deal with them first, before we see how we can aid Malfurion.  What do you say, small one?", sourceObjective = "Kill 8 Enraged Earth Elementals.", progress = "The land is deeply unsettled, {name}.  It'll be years before calm returns to these parts.", completion = "It's become clear, {name}.  The elements won't be calm until Malfurion succeeds in returning balance to the land.  Aiding him is, in a way, also fulfilling my task.", sourceObjectiveStatus = "unverified-source-field" }
quests[13585] = { id = 13585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sworn to Protect", description = "My duty here has been fulfilled as best it can.  Send word to Malfurion that I'll be joining him soon.\n\nGood luck to you, {name}.  Good luck to all of us.", sourceObjective = "Talk to Malfurion Stormrage at the Eye of the Vortex in Darkshore.", completion = "Excellent job, {name}!  Selenn's help in holding back the vortex will be invaluable.", sourceObjectiveStatus = "unverified-source-field" }
quests[13586] = { id = 13586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Dream", description = "Our efforts in containing the destruction don't appear to be quite enough.  I fear we're going to need aid from beyond the waking world.\n\nTwilight cultists inside the Earthshatter Cavern to the east have opened a gateway to a nightmare-infested section of the Emerald Dream.  They hold a green dragon prisoner named Thessera there.\n\nGo through the nightmare portal and free her.  She will be a powerful ally.", sourceObjective = "Step through the Nightmare Portal in the Earthshatter Cavern and speak to Thessera.", completion = "Malfurion calls?  Yes... I can hear his voice through the dream...", sourceObjectiveStatus = "unverified-source-field" }
quests[13587] = { id = 13587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waking Nightmare", description = "Malfurion's words are true, small one.  The rift that threatens to split Darkshore in half also threatens the separation between this world and yours.\n\nLet me aid you in any way that I can, lest further rifts between our worlds amplify the destruction taking place in both places.\n\nFirst you must undo the shackles cast upon me by retrieving the emerald scroll from the nightmare guardian that roams the halls below.", sourceObjective = "Obtain the Emerald Scroll from the Nightmare Guardian inside the Earthshatter Cavern.", progress = "Did you find it, {name}?", completion = "I thank you, {name}.  You've given me my freedom.  Let's see what we can do for your world now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13588] = { id = 13588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of All Storms", description = "Twilight riders circle the skies above the vortex.  I fear it is their magic that has kept the cataclysmic forces from being contained by our efforts.\n\nTake to the skies with Thessera and destroy the riders and the portal from whence they came.", sourceObjective = "Ride Thessera to defeat 12 Twilight Riders and destroy the Twilight Portal.", completion = "We are turning the tides, {name}.  We should be able to contain further damage.\n\nMuch work still remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13589] = { id = 13589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shatterspear Invaders", description = "If we didn't have enough on our hands with the land and the elements turning against us, it seems something has riled up the trolls to the northeast, and they've started on a war path. I'm not sure what their aims are, but they've already attacked several of our scouts and have besieged the cultists at the Tower of Althalaxx.\n\nWe've sent a contingent of our best Sentinels to counter their attacks. If you would travel northeast to the ruins and join them, I'm certain that they could use the extra hand.", sourceObjective = "Report to Lieutenant Morra Starbreeze at the Ruins of Mathystra.", completion = "Glynda sent you to lend a hand, did she? I'm glad she did - I could certainly use the help.\n\nI'm working on our initial plans to start whittling away at their ranks. Please feel free to help Tysha and Balthule in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[13590] = { id = 13590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Front Line", description = "Their forces are weakened, their supplies destroyed, and their subleaders are dead. It is time for us to take this fight to their home, and their leader. I'm admittedly still in the dark as to what spurred their sudden aggression, but perhaps we will find some answers on their doorstep.\n\nTake this arrow that Balthule prepared and report to Sandrya Moonfall deep in Shatterspear Vale to join the attack. It would be best to secure a ride on one of our nightsabers - going on foot would be dangerous.", sourceObjective = "Report to Huntress Sandrya Moonfall deep in Shatterspear Vale.", progress = "Greetings, {class}. Did you bring the arrow?", completion = "It is good to meet you. Word has been sent to me of the efforts you have made to aid us against the trolls, and I must admit I am a bit impressed. The final fight is upon us now, I hope you are prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[13591] = { id = 13591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Connections", description = "The letter from Garrosh Hellscream makes clear the suspicions that were raised during the offensive on the Shatterspear. The presence of forsaken at the tower ruins and horde supplies and enforcers at the Shatterspear War Camp were only the start. Garrosh himself contacted the Shatterspear to spur their offensive towards Lor'danel, and it seems clear that he fully intends to push from the south as well.\n\nGlynda Nal'Shea will need this information if the night elves are to be prepared.", sourceObjective = "Bring the Hellscream's Missive to Ranger Glynda Nal'Shea at Lor'danel.", progress = "You're back! I hear the battle went well.", completion = "Well, this news is disturbing indeed. I will start dispatching messengers to Ashenvale immediately and see if we can't get some reinforcements prepared for them.\n\nI cannot thank you enough for all the help you've lent us in these trying times. Such heroic deeds deserve reward. I think I might have something that will serve you perfectly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Stormwind", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.", completion = "We are proud that you have agreed to train with us and compete on our behalf.", sourceObjectiveStatus = "unverified-source-field" }
quests[13594] = { id = 13594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Horde", description = "Evenar and the other apprentices may not be much use in a battle, but you look like you can more than hold your own. The Horde scum across the road to the east at Bathran's Haunt need to be taught a lesson.\n\nTheir new warlord, Garrosh Hellscream, has them up to no good. Feel like teaching them a thing or two?\n\nI'd come with you, but my assignment is to stay here and protect Orendil's apprentices, and that's exactly what I'm going to do.", sourceObjective = "Kill any 10 Horde at Bathran's Haunt.", completion = "<The sentinel eyes you appreciatively for a moment.>\n\nA job well done, {class}. If you're any indication of the quality of the {race} adventurers we're going to be seeing more of, we should have this war against the orcs and their Horde taken care of faster than expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[13595] = { id = 13595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Their Own Design", description = "These creatures... these so-called Horde... they have cut me down in my prime and they are harvesting my hair for their evil plans.\n\nWill you help me to put an end to it, little {race}?\n\nI have overheard their herbalists speaking of something called wildfire upon their table across the way. If you were to take the bottle of this unnatural stuff and throw it at my corpse to the northeast, it would burn and no more of my hair will grow here.\n\nI am already dead and it is a small price to pay to stop them.", sourceObjective = "Obtain a Bottle of Wildfire and throw it at Bathran's Corpse to burn it.", progress = "Your lives are all so short. Why is it that you insist on squandering them by killing each other?", completion = "You have helped me to return to the ground, {name}.\n\nNow my hair will cease to sprout for these creatures. Better yet, I will be regrown all the sooner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13596] = { id = 13596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Plans", description = "We're not fully aware of the intentions of the Twilight's Hammer cultists to the southwest.  We fear an attack on Lor'danel, however their motives might go well beyond that.\n\nI need you to go to the Twilight Encampment and get your hands on their plans.  Hurry, {name}.  We might not have much time.", sourceObjective = "Obtain 6 Twilight Plans at the Twilight Encampment.", progress = "Have you obtained the plans yet, {name}?", completion = "Excellent job, {name}.  Now give me a moment to examine the plans you've brought me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13597] = { id = 13597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Thistle Bear", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Thistle Bear Spirit, take this incense to a cave just east of the great whirlpool. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Thistle Bear Spirit.", completion = "For countless ages I have walked these forests and lived in these mountains. Through snow and fire, I have watched civilizations crumble and nature press on. Now, the very earth turns against us, and it becomes very apparent that we must fight if our legacy is to continue.\n\nYour heart is true, and I would choose you as our champion. If you value the thick hide and resilience of my kind, then accept my boon. Know that the other spirits will not accept you once this choice is made, so choose wisely.", sourceObjectiveStatus = "unverified-source-field" }
quests[13598] = { id = 13598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsavory Remedies", description = "I have no doubts that Grimclaw will recover with the help of my healing magics, though I can't say the same for the poachers that attacked him. Still, I could use some salve to close his wounds and lessen his pain while he heals.\n\nTo the east you will find the Ruins of Lornesta. Among the crumbled stones, there is a variety of fuming toadstool that flourishes in the damp environment. Bring me some of the toadstools so that I can mix a salve for our friend here.", sourceObjective = "Recover 6 Fuming Toadstools.", progress = "Grimclaw is quite the fierce combatant. I feel somewhat sorry for those poachers, despite their aims.", completion = "You have my thanks, young one. We should be able to speed Grimclaw's recovery dramatically with this salve.", sourceObjectiveStatus = "unverified-source-field" }
quests[13599] = { id = 13599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimclaw's Return", description = "With the binding complete, the blessing has taken hold. It will most certainly make your travels in these lands easier.\n\nGrimclaw made a full recovery. Before I could do anything to stop him, he bolted off towards Lor'danel. I suppose that means it's time for your departure.\n\nIt was a great pleasure to have met you. For now, farewell - send my best wishes to Volcor and Grimclaw.", sourceObjective = "Return to Volcor and Grimclaw in Lor'danel.", completion = "You've returned! It is good to see you again. I suppose we have you to thank for Grimclaw's return?\n\nI'm afraid... I have some bad news. I've been unable to purge the toxin... their conditions worsen. Gershalla died shortly after you left, and Volcor... Volcor passed just before you came back.\n\nHe lived long enough to see Grimclaw come back safely, so he died with a smile on his face. I'm just sorry that I couldn't do more.\n\nFor now, I'm doing everything I can to save Shaldyn, so please excuse me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The marshal accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
